      expect(conv.turns.find((turn) => turn.id === "pfr")?.usage).toEqual({ inputTokens: 7, outputTokens: 3 });
      expect(sessionTokens(conv)).toEqual({ inputTokens: 8, outputTokens: 4, scope: "loaded" });
